type Validator<T> = Box<dyn Fn(&T) -> Result<(), String>>;

fn validate_all<T>(value: &T, validators: &[Validator<T>]) -> Result<(), Vec<String>> {
    let errors: Vec<_> = validators
        .iter()
        .filter_map(|v| v(value).err())
        .collect();

    if errors.is_empty() { Ok(()) } else { Err(errors) }
}

fn main() {
    let validators: Vec<Validator<String>> = vec![
        Box::new(|s| if s.len() >= 3 { Ok(()) } else { Err("too short".into()) }),
        Box::new(|s| if s.chars().any(|c| c.is_ascii_digit()) { Ok(()) } else { Err("no digit".into()) }),
    ];

    println!("{:?}", validate_all("ab", &validators));   // Err(["too short", "no digit"])
    println!("{:?}", validate_all("abc1", &validators)); // Ok(())
}
